from pathlib import Path
needles=['host-local readiness evidence','evidence-dir','dev-secondary.json','generated_at']
paths=[]
for p in Path('.').rglob('*'):
    if p.is_file() and '.git/' not in str(p):
        try:
            text=p.read_text(encoding='utf-8')
        except Exception:
            continue
        if any(n in text for n in needles):
            paths.append(str(p))
print('\n'.join(sorted(paths)))
